CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 VARCHAR2, arg4 VARCHAR2)
AS
BEGIN
  UPDATE "driver" d
     SET d."Name" = arg2
   WHERE d."Age" > arg1;

  UPDATE "school_bus" sb
     SET sb."Years_Working" = sb."Years_Working" + 1
   WHERE sb."Driver_ID" IN (
           SELECT d."Driver_ID"
             FROM "driver" d
            WHERE d."Age" > arg1
         );

  IF arg3 IS NOT NULL THEN
    UPDATE "school_bus" sb
       SET sb."If_full_time" = 'T'
     WHERE sb."Driver_ID" IN (
             SELECT d."Driver_ID"
               FROM "driver" d
              WHERE d."Age" > arg1
                AND d."Party" = arg3
           );
  END IF;

  DELETE FROM "driver" d
   WHERE d."Party" IS NULL;

  UPDATE "driver" d
     SET d."Home_city" = arg4;

  IF arg3 IS NOT NULL THEN
    UPDATE "driver" d
       SET d."Party" = arg3
     WHERE d."Age" > arg1;

    UPDATE "school_bus" sb
       SET sb."If_full_time" = 'F'
     WHERE sb."Driver_ID" IN (
             SELECT d."Driver_ID"
               FROM "driver" d
              WHERE d."Party" = arg3
                AND d."Age" <= arg1
           );
  END IF;
END sp;

